const content = String($json.content || '');

if (!content) {
  throw new Error('No content received.');
}

// Normalize the malformed escaped underscores.
// Converts:
// vessel\_name -> vessel_name
// utm\_date\_requested -> utm_date_requested
const cleaned = content.replace(/\\_/g, '_');

// Extract vessel name
const vesselMatch = cleaned.match(
  /["']?vessel_name["']?\s*:\s*["']([^"']+)["']/
);

// Extract UTM requested date
const dateMatch = cleaned.match(
  /["']?utm_date_requested["']?\s*:\s*["']([^"']+)["']/
);

const vesselName = vesselMatch
  ? vesselMatch[1].trim()
  : null;

const utmDate = dateMatch
  ? dateMatch[1].trim()
  : null;

if (!vesselName) {
  throw new Error(
    `Could not extract vessel_name.\n\nCleaned content:\n${cleaned}`
  );
}

if (!utmDate) {
  throw new Error(
    `Could not extract utm_date_requested.\n\nCleaned content:\n${cleaned}`
  );
}

return [
  {
    json: {
      vessel_name: vesselName,
      utm_date_requested: utmDate
    }
  }
];

const schedules = $json.vesselSchedules || [];

// Get the original extracted enquiry data
const extraction = $('Parse LLM Extraction').first().json;

const vesselName = extraction.vessel_name;
const utmDate = extraction.utm_date_requested;

return schedules.map((s, index) => {
  const arrival = new Date(s.arrivalTime);
  const departure = new Date(s.departureTime);

  const stayHours =
    (departure.getTime() - arrival.getTime()) / (1000 * 60 * 60);

  return {
    json: {
      vessel_name: vesselName,
      utm_date_requested: utmDate,

      sequence: index + 1,

      port: s.portName,
      city: s.cityName,
      country: s.countryName,
      country_code: s.isoCountryCode,
      un_location_code: s.unLocationCode,

      arrival: s.arrivalTime,
      departure: s.departureTime,

      stay_hours: Math.round(stayHours * 10) / 10,

      arrival_status: s.arrivalTimingClassifier,
      departure_status: s.departureTimingClassifier,

      arrival_voyage: s.arrivalVoyageNumber,
      departure_voyage: s.departureVoyageNumber,

      service: s.arrivalServiceName,
      service_code: s.arrivalServiceCode
    }
  };
});

const input = $json;

return {
  json: {
    email_from: input.From || input.from || "",
    email_to: input.To || input.to || "",
    email_subject: input.Subject || input.subject || "",
    email_date: input.Date || input.date || "",
    email_snippet: input.snippet || "",
    email_body: input.textPlain || input.text || input.body || ""
  }
};

const inputItems = $input.all();

if (!inputItems.length) {
  throw new Error('No vessel schedule data received.');
}

const extraction = $('Parse LLM Extraction').first().json;

const vesselName =
  extraction.vessel_name ||
  inputItems[0].json.vessel_name ||
  null;

const utmDateString =
  extraction.utm_date_requested ||
  inputItems[0].json.utm_date_requested ||
  null;

if (!utmDateString) {
  throw new Error('UTM requested date is missing.');
}

/*
 * ---------------------------------------------------------
 * REQUESTED DATE
 * ---------------------------------------------------------
 */

const requestedStart =
  new Date(`${utmDateString}T00:00:00`);

const requestedEnd =
  new Date(`${utmDateString}T23:59:59`);

if (
  Number.isNaN(requestedStart.getTime()) ||
  Number.isNaN(requestedEnd.getTime())
) {
  throw new Error(`Invalid UTM date: ${utmDateString}`);
}

/*
 * ---------------------------------------------------------
 * JOINING WINDOW
 *
 * 7 days before and 7 days after requested date.
 * ---------------------------------------------------------
 */

const windowStart = new Date(requestedStart);
windowStart.setDate(windowStart.getDate() - 7);

const windowEnd = new Date(requestedEnd);
windowEnd.setDate(windowEnd.getDate() + 7);

/*
 * ---------------------------------------------------------
 * BUILD CANDIDATES
 * ---------------------------------------------------------
 */

const candidates = [];

for (const item of inputItems) {

  const schedule = item.json;

  if (
    !schedule.port ||
    !schedule.arrival ||
    !schedule.departure
  ) {
    continue;
  }

  const arrival = new Date(schedule.arrival);
  const departure = new Date(schedule.departure);

  if (
    Number.isNaN(arrival.getTime()) ||
    Number.isNaN(departure.getTime())
  ) {
    continue;
  }

  /*
   * Keep the call if any part of the vessel's
   * port stay falls inside our joining window.
   */
  const overlapsWindow =
    arrival <= windowEnd &&
    departure >= windowStart;

  if (!overlapsWindow) {
    continue;
  }

  /*
   * -------------------------------------------------------
   * IS VESSEL IN PORT ON REQUESTED DATE?
   * -------------------------------------------------------
   */

  const inPortOnRequestedDate =
    arrival <= requestedEnd &&
    departure >= requestedStart;

  /*
   * -------------------------------------------------------
   * DISTANCE FROM REQUESTED DATE
   * -------------------------------------------------------
   */

  let daysFromRequestedDate = 0;

  if (inPortOnRequestedDate) {

    daysFromRequestedDate = 0;

  } else if (departure < requestedStart) {

    daysFromRequestedDate =
      (
        requestedStart.getTime() -
        departure.getTime()
      ) /
      (1000 * 60 * 60 * 24);

  } else {

    daysFromRequestedDate =
      (
        arrival.getTime() -
        requestedEnd.getTime()
      ) /
      (1000 * 60 * 60 * 24);
  }

  /*
   * -------------------------------------------------------
   * DATE RELATION
   * -------------------------------------------------------
   */

  let dateRelation;

  if (inPortOnRequestedDate) {

    dateRelation =
      'VESSEL_IN_PORT_ON_REQUESTED_DATE';

  } else if (departure < requestedStart) {

    dateRelation =
      'VESSEL_DEPARTS_BEFORE_REQUESTED_DATE';

  } else if (arrival > requestedEnd) {

    dateRelation =
      'VESSEL_ARRIVES_AFTER_REQUESTED_DATE';

  } else {

    dateRelation =
      'WITHIN_JOINING_WINDOW';
  }

  /*
   * -------------------------------------------------------
   * PORT STAY
   * -------------------------------------------------------
   */

  const stayHours =
    (
      departure.getTime() -
      arrival.getTime()
    ) /
    (1000 * 60 * 60);

  /*
   * -------------------------------------------------------
   * PRELIMINARY SCORE
   * -------------------------------------------------------
   */

  let score = 0;

  /*
   * The requested date being inside the vessel's
   * port stay is the strongest criterion.
   */
  if (inPortOnRequestedDate) {
    score += 100;
  }

  /*
   * Distance penalty.
   */
  score -= daysFromRequestedDate * 10;

  /*
   * Port stay preference.
   */
  if (stayHours >= 48) {
    score += 20;
  } else if (stayHours >= 24) {
    score += 15;
  } else if (stayHours >= 12) {
    score += 8;
  }

  /*
   * Schedule confidence.
   */
  const status =
    String(schedule.arrival_status || schedule.schedule_status || '')
      .toUpperCase();

  if (status === 'SCHEDULED') {
    score += 10;
  } else if (status === 'ESTIMATED') {
    score += 5;
  }

  candidates.push({

    vessel_name:
      vesselName,

    utm_date_requested:
      utmDateString,

    option_type:
      'POSSIBLE_JOINING_PORT',

    join_port:
      schedule.port,

    join_city:
      schedule.city || schedule.port,

    join_country:
      schedule.country || null,

    join_country_code:
      schedule.country_code || null,

    join_un_location_code:
      schedule.un_location_code || null,

    vessel_arrival:
      schedule.arrival,

    vessel_departure:
      schedule.departure,

    port_stay_hours:
      Math.round(stayHours * 10) / 10,

    schedule_status:
      schedule.arrival_status ||
      schedule.schedule_status ||
      null,

    arrival_voyage:
      schedule.arrival_voyage ||
      null,

    departure_voyage:
      schedule.departure_voyage ||
      null,

    service:
      schedule.service ||
      null,

    service_code:
      schedule.service_code ||
      null,

    days_from_requested_date:
      Math.round(daysFromRequestedDate * 10) / 10,

    date_relation:
      dateRelation,

    vessel_in_port_on_requested_date:
      inPortOnRequestedDate,

    preliminary_suitability_score:
      Math.round(score * 10) / 10
  });
}

/*
 * ---------------------------------------------------------
 * REMOVE DUPLICATES
 * ---------------------------------------------------------
 */

const unique = [];

const seen = new Set();

for (const candidate of candidates) {

  const key = [
    candidate.join_un_location_code,
    candidate.vessel_arrival,
    candidate.vessel_departure
  ].join('|');

  if (seen.has(key)) {
    continue;
  }

  seen.add(key);
  unique.push(candidate);
}

/*
 * ---------------------------------------------------------
 * SORT
 *
 * 1. In port on requested date
 * 2. Preliminary score
 * 3. Closest to requested date
 * 4. Longest port stay
 * ---------------------------------------------------------
 */

unique.sort((a, b) => {

  if (
    a.vessel_in_port_on_requested_date !==
    b.vessel_in_port_on_requested_date
  ) {
    return (
      Number(b.vessel_in_port_on_requested_date) -
      Number(a.vessel_in_port_on_requested_date)
    );
  }

  if (
    a.preliminary_suitability_score !==
    b.preliminary_suitability_score
  ) {
    return (
      b.preliminary_suitability_score -
      a.preliminary_suitability_score
    );
  }

  if (
    a.days_from_requested_date !==
    b.days_from_requested_date
  ) {
    return (
      a.days_from_requested_date -
      b.days_from_requested_date
    );
  }

  return (
    b.port_stay_hours -
    a.port_stay_hours
  );
});

/*
 * ---------------------------------------------------------
 * OUTPUT
 * ---------------------------------------------------------
 */

return unique
  .slice(0, 10)
  .map((candidate, index) => ({
    json: {
      ...candidate,
      option_number: index + 1
    }
  }));

const items = $input.all();

if (!items.length) {
  throw new Error('No joining options received.');
}

// Get vessel/enquiry information
const first = items[0].json;

const vesselName = first.vessel_name;
const utmDate = first.utm_date_requested;

// Temporary member information
// Later these values will come from the form.

const members = [
  {
    member_id: 1,
    member_name: "Member 1",
    origin_city: "Mumbai",
    origin_country: "India",
    available_from: utmDate,
    available_until: utmDate,

    // Temporary visa assumption.
    // We will replace this with the actual form data later.
    visa_permissions: []
  },

  {
    member_id: 2,
    member_name: "Member 2",
    origin_city: "Mumbai",
    origin_country: "India",
    available_from: utmDate,
    available_until: utmDate,

    visa_permissions: []
  }
];

return [
  {
    json: {
      vessel_name: vesselName,
      utm_date_requested: utmDate,

      joining_options: items.map(item => item.json),

      members
    }
  }
];

const input = $input.first().json;

if (!input) {
  throw new Error('No UTM planning data received.');
}

const members = input.members || [];
const joiningOptions = input.joining_options || [];

if (!members.length) {
  throw new Error('No UTM members found.');
}

if (!joiningOptions.length) {
  throw new Error('No vessel joining options found.');
}

const queries = [];

for (const member of members) {
  for (const option of joiningOptions) {

    queries.push({
      json: {
        // -----------------------------
        // VESSEL
        // -----------------------------
        vessel_name: input.vessel_name,
        utm_date_requested: input.utm_date_requested,

        // -----------------------------
        // MEMBER
        // -----------------------------
        member_id: member.member_id,
        member_name: member.member_name,

        origin_city: member.origin_city,
        origin_country: member.origin_country,

        member_available_from:
          member.available_from || null,

        member_available_until:
          member.available_until || null,

        visa_permissions:
          member.visa_permissions || [],

        // -----------------------------
        // DESTINATION
        // -----------------------------
        destination_port:
          option.join_port,

        destination_city:
          option.join_city,

        destination_country:
          option.join_country,

        destination_country_code:
          option.join_country_code || null,

        un_location_code:
          option.join_un_location_code || null,

        // -----------------------------
        // VESSEL SCHEDULE
        // -----------------------------
        vessel_arrival:
          option.vessel_arrival,

        vessel_departure:
          option.vessel_departure,

        port_stay_hours:
          option.port_stay_hours || null,

        schedule_status:
          option.schedule_status || null,

        date_relation:
          option.date_relation || null,

        // -----------------------------
        // TRAVEL SEARCH
        // -----------------------------
        origin_iata: null,
        destination_iata: null,

        travel_search_date:
          member.available_from ||
          input.utm_date_requested,

        travel_time_hours: null,
        travel_distance_km: null,

        travel_status:
          "PENDING_AIRPORT_RESOLUTION",

        // -----------------------------
        // VISA
        // -----------------------------
        visa_status:
          member.visa_permissions &&
          member.visa_permissions.length > 0
            ? "PROVIDED"
            : "REQUIRES_CONFIRMATION",

        // -----------------------------
        // ROUTE
        // -----------------------------
        route_status:
          "PENDING_TRAVEL_DATA"
      }
    });
  }
}

return queries;

const items = $input.all();

const airportMap = {
  "Mumbai": {
    iata: "BOM",
    airport: "Chhatrapati Shivaji Maharaj International Airport"
  },

  "Beirut": {
    iata: "BEY",
    airport: "Beirut-Rafic Hariri International Airport"
  }
};

return items.map(item => {

  const data = item.json;

  const origin = airportMap[data.origin_city];
  const destination = airportMap[data.destination_city];

  const resolved = !!(origin && destination);

  return {
    json: {
      ...data,

      origin_iata:
        origin ? origin.iata : null,

      origin_airport:
        origin ? origin.airport : null,

      destination_iata:
        destination ? destination.iata : null,

      destination_airport:
        destination ? destination.airport : null,

      airport_resolution_status:
        resolved
          ? "RESOLVED"
          : "REQUIRES_AIRPORT_MAPPING",

      travel_status:
        resolved
          ? "PENDING_TRAVEL_DATA"
          : "PENDING_AIRPORT_RESOLUTION"
    }
  };
});

const items = $input.all();

if (!items.length) {
  throw new Error('No travel route items received.');
}

// Create one geocoding request per unique vessel port.
const uniquePorts = new Map();

for (const item of items) {
  const data = item.json;

  const portName =
    data.destination_port ||
    data.destination_city ||
    null;

  const country =
    data.destination_country ||
    null;

  if (!portName) continue;

  const key = `${String(portName).trim().toLowerCase()}|${String(country).trim().toLowerCase()}`;

  if (!uniquePorts.has(key)) {
    uniquePorts.set(key, {
      port_name: portName,
      country: country,
      geocode_query: `${portName}, ${country}`
    });
  }
}

const output = Array.from(uniquePorts.values()).map(port => ({
  json: {
    port_name: port.port_name,
    country: port.country,
    port_geocode_query: port.geocode_query,
    port_geocode_status: 'READY'
  }
}));

if (!output.length) {
  throw new Error('No vessel ports available for geocoding.');
}

return output;

const items = $input.all();

const output = [];

for (const item of items) {

  const input = item.json;

  /*
   * If n8n has split Nominatim results into separate items,
   * collect all items belonging to this port search.
   */
  const results = items.map(i => i.json);

  if (!results.length) {
    output.push({
      json: {
        ...input,
        port_geocode_status: "NO_PORT_RESULT_FOUND"
      }
    });
    continue;
  }

  const ranked = results.map(result => {

    const name =
      String(result.name || "").toLowerCase();

    const displayName =
      String(result.display_name || "").toLowerCase();

    const type =
      String(result.type || "").toLowerCase();

    const category =
      String(result.category || "").toLowerCase();

    const addresstype =
      String(result.addresstype || "").toLowerCase();

    const forbiddenTypes = [
      "administrative",
      "boundary",
      "city",
      "town",
      "village",
      "municipality",
      "suburb",
      "neighbourhood",
      "district",
      "state",
      "county",
      "region"
    ];

    const isForbidden =
      forbiddenTypes.includes(type) ||
      forbiddenTypes.includes(addresstype) ||
      category === "boundary";

    if (isForbidden) {
      return {
        result,
        score: -10000,
        rejected: true
      };
    }

    let score = 0;

    if (type === "harbour") score += 200;

    if (addresstype === "harbour") score += 150;

    const maritimeTypes = [
      "port",
      "marina",
      "dock",
      "pier",
      "quay",
      "terminal"
    ];

    if (maritimeTypes.includes(type)) {
      score += 120;
    }

    if (maritimeTypes.includes(addresstype)) {
      score += 100;
    }

    if (
      name.includes("port") ||
      name.includes("harbour") ||
      name.includes("harbor") ||
      name.includes("terminal") ||
      name.includes("marina")
    ) {
      score += 50;
    }

    if (
      displayName.includes("port") ||
      displayName.includes("harbour") ||
      displayName.includes("harbor") ||
      displayName.includes("terminal") ||
      displayName.includes("marina")
    ) {
      score += 30;
    }

    if (type === "industrial") {
      score -= 50;
    }

    if (
      result.lat &&
      result.lon &&
      Number.isFinite(Number(result.lat)) &&
      Number.isFinite(Number(result.lon))
    ) {
      score += 20;
    } else {
      score -= 10000;
    }

    return {
      result,
      score,
      rejected: false
    };

  });

  const validRanked = ranked
    .filter(item => !item.rejected)
    .sort((a, b) => b.score - a.score);

  const best = validRanked[0]?.result;

  if (
    !best ||
    !best.lat ||
    !best.lon
  ) {

    /*
     * Only output this once if no maritime result exists.
     */
    if (items.indexOf(item) !== 0) continue;

    output.push({
      json: {
        ...input,

        selected_port_name: null,
        selected_port_display_name: null,
        selected_port_type: null,
        selected_port_category: null,

        port_latitude: null,
        port_longitude: null,

        port_place_id: null,
        port_osm_type: null,
        port_osm_id: null,

        port_geocode_status:
          "NO_VALID_MARITIME_PORT_FOUND",

        port_selection_method:
          "HARBOUR_PRIORITY"
      }
    });

    continue;
  }

  /*
   * Only output the best maritime result.
   */
  if (items.indexOf(item) !== 0) {
    continue;
  }

  output.push({
    json: {

      ...input,

      selected_port_name:
        best.name || null,

      selected_port_display_name:
        best.display_name || null,

      selected_port_type:
        best.type || null,

      selected_port_category:
        best.category || null,

      port_latitude:
        Number(best.lat),

      port_longitude:
        Number(best.lon),

      port_place_id:
        best.place_id || null,

      port_osm_type:
        best.osm_type || null,

      port_osm_id:
        best.osm_id || null,

      port_geocode_status:
        "PORT_COORDINATES_FOUND",

      port_selection_method:
        "HARBOUR_PRIORITY"
    }
  });
}

return output;

const items = $input.all();

const uniquePorts = new Map();

for (const item of items) {
  const data = item.json;

  const lat = Number(data.port_latitude);
  const lon = Number(data.port_longitude);

  if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
    continue;
  }

  const portName =
    data.selected_port_name ||
    data.destination_port ||
    data.join_port ||
    data.vessel_port ||
    null;

  const portDisplayName =
    data.selected_port_display_name ||
    data.vessel_port_display_name ||
    null;

  const country =
    data.destination_country ||
    data.join_country ||
    data.country ||
    null;

  const key = `${lat.toFixed(5)},${lon.toFixed(5)}`;

  if (!uniquePorts.has(key)) {
    uniquePorts.set(key, {
      port_key: key,
      port_name: portName,
      port_display_name: portDisplayName,
      port_latitude: lat,
      port_longitude: lon,
      country: country
    });
  }
}

const ports = Array.from(uniquePorts.values());

if (!ports.length) {
  throw new Error('No vessel ports with valid coordinates were found.');
}

/*
 * Lightweight Overpass query.
 *
 * Only airport nodes with IATA codes are requested.
 * 75 km is sufficient for practical airport discovery.
 */

const queries = ports.map(port => `
  node
    ["aeroway"="aerodrome"]
    ["iata"]
    (around:75000,${port.port_latitude},${port.port_longitude});
`).join('\n');

const overpassQuery = `
[out:json][timeout:30];

(
${queries}
);

out tags;
`;

return [{
  json: {
    port_count: ports.length,
    ports,
    overpass_query: overpassQuery
  }
}];

// Rank airports returned by Overpass
// based on suitability for UTM crew travel.

const input = $input.first().json;

// --------------------------------------------------
// 1. Get the airport results from Overpass
// --------------------------------------------------

const elements = input.elements || [];

if (!Array.isArray(elements) || elements.length === 0) {
  throw new Error('No airport results returned from Overpass.');
}

// --------------------------------------------------
// 2. Recover the vessel-port information
// --------------------------------------------------
// Prepare Airport Search produced the unique ports.
// We fetch that information from the previous node.

const airportSearch = $('Prepare Airport Search').first().json;

const ports = airportSearch.ports || [];

if (!Array.isArray(ports) || ports.length === 0) {
  throw new Error('No vessel-port coordinates found from Prepare Airport Search.');
}

// --------------------------------------------------
// 3. Haversine distance
// --------------------------------------------------

function distanceKm(lat1, lon1, lat2, lon2) {
  const R = 6371;

  const toRad = value => value * Math.PI / 180;

  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);

  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) *
    Math.cos(toRad(lat2)) *
    Math.sin(dLon / 2) ** 2;

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return R * c;
}

// --------------------------------------------------
// 4. Extract airport coordinates
// --------------------------------------------------

function getAirportCoordinates(airport) {
  let lat = airport.lat;
  let lon = airport.lon;

  // Ways/relations may return coordinates under "center"
  if ((!lat || !lon) && airport.center) {
    lat = airport.center.lat;
    lon = airport.center.lon;
  }

  if (!lat || !lon) {
    return null;
  }

  return {
    lat: Number(lat),
    lon: Number(lon)
  };
}

// --------------------------------------------------
// 5. Convert airport records
// --------------------------------------------------

const airports = [];

for (const airport of elements) {

  const coordinates = getAirportCoordinates(airport);

  if (!coordinates) {
    continue;
  }

  const tags = airport.tags || {};

  const name =
    tags['name:en'] ||
    tags.name ||
    tags['int_name'] ||
    tags['official_name'] ||
    null;

  const iata =
    tags.iata ||
    null;

  const icao =
    tags.icao ||
    null;

  const aeroway =
    tags.aeroway ||
    null;

  // ------------------------------------------------
  // Determine airport characteristics
  // ------------------------------------------------

  const nameLower = String(name || '').toLowerCase();

  const militaryKeywords = [
    'military',
    'air base',
    'airbase',
    'air force',
    'army air',
    'naval air'
  ];

  const isMilitary =
    militaryKeywords.some(keyword =>
      nameLower.includes(keyword)
    );

  const hasIata = !!iata;

  // ------------------------------------------------
  // Match airport to nearest vessel port
  // ------------------------------------------------

  let nearestPort = null;
  let nearestDistance = Infinity;

  for (const port of ports) {

    const portLat = Number(port.port_latitude);
    const portLon = Number(port.port_longitude);

    if (!Number.isFinite(portLat) || !Number.isFinite(portLon)) {
      continue;
    }

    const distance = distanceKm(
      coordinates.lat,
      coordinates.lon,
      portLat,
      portLon
    );

    if (distance < nearestDistance) {
      nearestDistance = distance;
      nearestPort = port;
    }
  }

  if (!nearestPort) {
    continue;
  }

  // ------------------------------------------------
  // Airport suitability score
  // ------------------------------------------------

  let score = 0;

  // Prefer IATA airports
  if (hasIata) {
    score += 30;
  }

  // Prefer proper airports
  if (aeroway === 'aerodrome') {
    score += 10;
  }

  // Strongly penalize military facilities
  if (isMilitary) {
    score -= 100;
  }

  // Distance score
  if (nearestDistance <= 25) {
    score += 40;
  } else if (nearestDistance <= 50) {
    score += 30;
  } else if (nearestDistance <= 75) {
    score += 20;
  } else if (nearestDistance <= 100) {
    score += 10;
  } else {
    score -= 10;
  }

  airports.push({
    airport_name: name,
    airport_name_local: tags.name || null,

    iata_code: iata,
    icao_code: icao,

    airport_type: aeroway,

    latitude: coordinates.lat,
    longitude: coordinates.lon,

    is_military: isMilitary,
    has_iata: hasIata,

    vessel_port: nearestPort.port_name,
    vessel_port_display_name: nearestPort.port_display_name,

    port_latitude: nearestPort.port_latitude,
    port_longitude: nearestPort.port_longitude,

    straight_line_distance_km:
      Math.round(nearestDistance * 100) / 100,

    suitability_score: score
  });
}

