  const vesselDeparture = new Date(data.vessel_departure);

  const groundTravelMinutes = Number(data.ground_travel_minutes);

  if (
    !Number.isFinite(requestedDate.getTime()) ||
    !Number.isFinite(vesselArrival.getTime()) ||
    !Number.isFinite(vesselDeparture.getTime())
  ) {
    output.push({
