        ...data,
        timing_status: "INVALID_DATE_DATA",
        route_status: "TIMING_CALCULATION_FAILED"
      }
    });

    continue;
  }

  /*
   * Buffer before vessel departure.
   *
   * This is deliberately conservative.
   * We want the UTM member to reach the vessel port
   * before the vessel's scheduled departure.
   */
  const safetyBufferHours = 12;

  const groundTravelHours =
    Number.isFinite(groundTravelMinutes)
      ? groundTravelMinutes / 60
      : null;

  /*
   * Latest safe arrival at the vessel port.
   */
  const latestSafePortArrival =
    new Date(
      vesselDeparture.getTime() -
      (safetyBufferHours * 60 * 60 * 1000)
    );

  /*
   * Latest time the member should leave the airport
   * to reach the vessel port by the safe-arrival deadline.
   */
  const latestAirportDeparture =
    groundTravelHours !== null
      ? new Date(
          latestSafePortArrival.getTime() -
          (groundTravelHours * 60 * 60 * 1000)
        )
      : null;

  /*
   * Check whether the requested UTM date falls
   * while the vessel is actually in port.
   */
  const vesselInPortOnRequestedDate =
    requestedDate >= vesselArrival &&
    requestedDate <= vesselDeparture;

  /*
   * Check whether the vessel is still in port
   * on the requested date.
   */
  const requestedDateWithinPortStay =
    requestedDate >= vesselArrival &&
    requestedDate < vesselDeparture;

  /*
   * Determine whether this is potentially usable.
   *
   * We do NOT yet perform visa or flight availability checks.
   * Those come later.
   */
  let timingStatus = "CHECK_REQUIRED";
  let routeStatus = "TIMING_CHECK_REQUIRED";

  if (requestedDateWithinPortStay) {
    timingStatus = "REQUESTED_DATE_WITHIN_VESSEL_PORT_STAY";
    routeStatus = "TIMING_POTENTIALLY_FEASIBLE";
  }
  else if (vesselDeparture < requestedDate) {
    timingStatus = "VESSEL_DEPARTS_BEFORE_REQUESTED_DATE";
    routeStatus = "NOT_FEASIBLE_DATE_MISMATCH";
  }
  else if (vesselArrival > requestedDate) {
    timingStatus = "VESSEL_ARRIVES_AFTER_REQUESTED_DATE";
    routeStatus = "CHECK_ALTERNATIVE_JOINING_DATE";
  }

  output.push({
    json: {
      ...data,

      // Timing assumptions
      safety_buffer_hours: safetyBufferHours,

      // Travel
      ground_travel_hours:
        groundTravelHours !== null
          ? Math.round(groundTravelHours * 100) / 100
          : null,

      // Vessel timing
      vessel_in_port_on_requested_date:
        vesselInPortOnRequestedDate,

