function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/*
 * Convert known Arabic/location names into stable
 * English comparison names.
 */
function locationTokens(value) {

  const raw = String(value || '').trim();
  const n = normalize(raw);

  const tokens = new Set();

  if (n) {
    tokens.add(n);
  }

  /*
   * Beirut
   */
  if (
    raw.includes('بيروت') ||
    n.includes('beirut')
  ) {
    tokens.add('beirut');
  }

  /*
   * Port Said
   */
  if (
    raw.includes('بورسعيد') ||
    n.includes('port said')
  ) {
    tokens.add('port said');
  }

  /*
   * Port Said East / West should still
   * be treated as Port Said for matching.
   */
  if (
    n.includes('port said east') ||
    n.includes('port said west')
  ) {
    tokens.add('port said');
  }

  return Array.from(tokens);
}

function matchLocation(route, airport) {

  const routeValues = [
    route.destination_port,
    route.destination_city
  ]
    .filter(Boolean);

  const airportValues = [
    airport.vessel_port,
    airport.vessel_port_display_name
  ]
    .filter(Boolean);

  const routeTokens = [];

  for (const value of routeValues) {
    routeTokens.push(...locationTokens(value));
  }

  const airportTokens = [];

  for (const value of airportValues) {
    airportTokens.push(...locationTokens(value));
  }

  /*
   * Exact normalized/alias match.
   */
  for (const r of routeTokens) {
    for (const a of airportTokens) {

      if (!r || !a) continue;

      if (r === a) {
        return true;
      }

      /*
       * Partial match for longer names.
       */
      if (
        r.length >= 5 &&
        a.length >= 5 &&
        (r.includes(a) || a.includes(r))
      ) {
        return true;
      }
    }
  }

  return false;
}

