  const d = item.json;

  const timingStatus = String(d.timing_status || '');
  const routeStatus = String(d.route_status || '');

  const isFeasible =
    timingStatus === 'REQUESTED_DATE_WITHIN_VESSEL_PORT_STAY' &&
    routeStatus === 'TIMING_POTENTIALLY_FEASIBLE';

  let score = 0;

  // Feasibility is the most important factor
  if (isFeasible) {
    score += 1000;
  } else {
    score -= 1000;
  }

  // Requested date alignment
  if (d.vessel_in_port_on_requested_date === true) {
    score += 200;
  }

  if (d.requested_date_within_port_stay === true) {
    score += 200;
  }

  // Airport quality
  score += Number(d.final_airport_score || 0);

  // Ground travel
  const groundMinutes = Number(d.ground_travel_minutes);

  if (Number.isFinite(groundMinutes)) {
    if (groundMinutes <= 30) {
      score += 50;
    } else if (groundMinutes <= 60) {
      score += 30;
    } else if (groundMinutes <= 120) {
      score += 10;
    } else {
      score -= 20;
    }
  }

  // Schedule confidence
  const scheduleStatus =
    String(d.schedule_status || '').toUpperCase();

  if (scheduleStatus === 'SCHEDULED') {
    score += 30;
  } else if (scheduleStatus === 'ESTIMATED') {
    score += 10;
  }

  // Visa information is pending, not an automatic rejection
  const visaStatus =
    String(d.visa_status || '').toUpperCase();

  if (visaStatus === 'REQUIRES_CONFIRMATION') {
    score -= 10;
  }

  let rejectionReason = null;

  if (!isFeasible) {
    if (
      timingStatus ===
      'VESSEL_DEPARTS_BEFORE_REQUESTED_DATE'
    ) {
      rejectionReason =
        'VESSEL_DEPARTS_BEFORE_UTM_REQUESTED_DATE';
    } else if (
      timingStatus ===
      'VESSEL_ARRIVES_AFTER_REQUESTED_DATE'
    ) {
      rejectionReason =
        'VESSEL_ARRIVES_AFTER_UTM_REQUESTED_DATE';
    } else {
      rejectionReason =
        'TIMING_OR_ROUTE_NOT_FEASIBLE';
    }
  }

  plans.push({
    ...d,

    plan_feasible: isFeasible,

    recommendation_score: score,

    recommendation_status: isFeasible
      ? (
          visaStatus === 'REQUIRES_CONFIRMATION'
            ? 'FEASIBLE_PENDING_VISA_CONFIRMATION'
            : 'FEASIBLE'
        )
      : 'NOT_FEASIBLE',

    rejection_reason: rejectionReason
  });
}

// Best plans first
plans.sort((a, b) => {
  return (
    Number(b.recommendation_score) -
    Number(a.recommendation_score)
  );
});

// Assign rank
plans.forEach((plan, index) => {
  plan.plan_rank = index + 1;
});

// Only feasible plans can become recommendations
const top3 = plans
  .filter(plan => plan.plan_feasible)
  .slice(0, 3);

return [
  {
    json: {
      vessel_name:
        plans[0]?.vessel_name || null,

      utm_date_requested:
        plans[0]?.utm_date_requested || null,

      total_plans_evaluated:
        plans.length,

      feasible_plan_count:
        plans.filter(p => p.plan_feasible).length,

      infeasible_plan_count:
        plans.filter(p => !p.plan_feasible).length,

      top_3_recommended_plans:
        top3.map((plan, index) => ({
          recommendation_rank: index + 1,

          member_id:
            plan.member_id,

          member_name:
            plan.member_name,

          origin_city:
            plan.origin_city,

          origin_country:
            plan.origin_country,

          joining_port:
            plan.destination_port,

          joining_city:
            plan.destination_city,

          joining_country:
            plan.destination_country,

          vessel_arrival:
            plan.vessel_arrival,

          vessel_departure:
            plan.vessel_departure,

          port_stay_hours:
            plan.port_stay_hours,

          selected_airport_name:
            plan.selected_airport_name,

          selected_airport_iata:
            plan.selected_airport_iata,

          selected_airport_icao:
            plan.selected_airport_icao,

          ground_distance_km:
            plan.ground_distance_km,

          ground_travel_minutes:
            plan.ground_travel_minutes,

          schedule_status:
            plan.schedule_status,

          recommendation_score:
            plan.recommendation_score,

          recommendation_status:
            plan.recommendation_status,

          visa_status:
            plan.visa_status
        })),

      all_evaluated_plans:
        plans.map(plan => ({
          plan_rank:
            plan.plan_rank,

          member_id:
            plan.member_id,

          member_name:
            plan.member_name,

          joining_port:
            plan.destination_port,

          vessel_arrival:
            plan.vessel_arrival,

          vessel_departure:
            plan.vessel_departure,

          plan_feasible:
            plan.plan_feasible,

          recommendation_score:
            plan.recommendation_score,

          recommendation_status:
            plan.recommendation_status,

          rejection_reason:
            plan.rejection_reason
        }))
    }
  }
];

const items = $input.all();

if (!items.length) {
  throw new Error('No UTM joining options received.');
}

const first = items[0].json;

const vesselName = first.vessel_name || null;
const utmDate = first.utm_date_requested || null;

if (!vesselName) {
  throw new Error('Vessel name missing from joining options.');
}

if (!utmDate) {
  throw new Error('UTM requested date missing from joining options.');
}

// Create a unique enquiry/project ID.
// For now this is generated from vessel + requested date.
const safeVessel = vesselName
  .replace(/[^a-zA-Z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .toUpperCase();

const projectId = `VSL-${safeVessel}-${utmDate}`;

return [
  {
    json: {
      project_id: projectId,
      vessel_name: vesselName,
      utm_date_requested: utmDate,

      joining_options: items.map(item => item.json),

      form_status: 'READY_FOR_UTM_MEMBER_DETAILS'
    }
  }
];

const data = $input.first().json;

const formUrl =
  `${$env.N8N_BASE_URL || 'http://localhost:5678'}/form/5f3c2a9e-1d47-4b8a-9c6e-2e0b7d41a8f3`;

return [{
  json: {
    ...data,

    utm_form_url: formUrl,

    utm_form_action_label:
      'FIND BEST ROUTES FROM CURRENT LOCATION'
  }
}];
